function cashMetrics(){const bs=r=>fv('balance',r),debt=strictSum([36,41,45,37,42].map(bs)),currentDebt=strictSum([41,42,45].map(bs)),assets=bs(22),liabilities=bs(47),cash=bs(21),investment=bs(20),ocf=cf(13),capex=strictSum([cf(16),cf(17)]),selected=ids(),continuous=selected.every((m,i)=>!i||m===selected[i-1]+1);return{assets,liabilities,cash,investment,ocf,capex,debt,currentDebt,netDebt:sub(debt,cash),nwc:sub(assets,liabilities),exInvestment:sub(assets,investment),currentRatio:ratio(assets,liabilities),cashRatio:ratio(cash,liabilities),receivableCoverage:ratio(strictSum([cash,bs(18)]),liabilities),exInvestmentRatio:ratio(sub(assets,investment),liabilities),afterCapex:strictSum([ocf,capex]),continuous,cashRoll:continuous?sub(strictSum([cf(33),cf(32)]),cf(34)):null};}
const times=x=>x===null?'—':num(x,2)+'×';
cashView=function(){const m=cashMetrics(),last=ids().at(-1),end=periodMonthLabel(last),opening=priorPeriod(),start=months[opening.month]+' '+opening.year,bs=r=>fv('balance',r),move=r=>sub(bs(r),priorBalance(r)),labels=ids().map(periodMonthLabel),trend=(title,series,fmt=money)=>reviewChart(title,series,labels,fmt),note=(text)=>`<p>${text}</p>`,signals=[];
if(m.nwc!==null)signals.push(note(`Closing current assets ${m.nwc<0?'fall short of':'exceed'} current liabilities by <strong>${money(Math.abs(m.nwc))} ${unit()}</strong>. The current ratio is ${times(m.currentRatio)}.`));
if(m.investment!==null&&m.assets>0)signals.push(note(`Short-term investments represent <strong>${pct(percent(m.investment,m.assets))}</strong> of current assets. Excluding these investments, current-asset coverage is ${times(m.exInvestmentRatio)}; their cash availability is not established by the source.`));
if(m.ocf!==null&&m.afterCapex!==null)signals.push(note(`Operating activities ${m.ocf<0?'used':'generated'} <strong>${money(Math.abs(m.ocf))} ${unit()}</strong>. Cash after the reported PPE and CWIP payments is ${money(m.afterCapex)} ${unit()}, before financing and other investing flows.`));
if(m.debt>0&&m.currentDebt!==null)signals.push(note(`Current bank and lease liabilities are <strong>${pct(percent(m.currentDebt,m.debt))}</strong> of total reported bank and lease debt. This indicates the current portion of funding obligations; a repayment schedule is not supplied.`));
return `<div class="cards">${card('Closing cash',money(m.cash),unit()+' · balance sheet at '+end)}${card('Operating cash flow',money(m.ocf),unit()+' · formal direct-method statement')}${card('Net cash movement',money(cf(32)),unit()+' · selected months')}${card('Net working capital',money(m.nwc),unit()+' · current assets less current liabilities')}</div><div class="grid">`+
panel('Operating cash & cash balance','Monthly flows and month-end balances · '+unit(),trend('Operating cash and closing balance',[trendSeries('Operating cash flow',month=>fv('cashflow',13,month)),trendSeries('CFS closing cash',month=>fv('cashflow',34,month)),trendSeries('BS closing cash',month=>fv('balance',21,month))]))+
panel('Cash sources and uses',period()+' · Signed source cash flows; capex is already included in investing.',table(['Measure',unit()],[[finLink('cashflow',13,'Operating cash flow'),money(m.ocf)],[finLink('cashflow',20,'Investing cash flow'),money(cf(20))],[finLink('cashflow',30,'Financing cash flow'),money(cf(30))],[finLink('cashflow',29,'Intercompany net within financing'),money(cf(29))],['PPE + CWIP cash flows (within investing)',money(m.capex)],['Cash after PPE and CWIP payments',money(m.afterCapex)],[finLink('cashflow',32,'Net cash movement'),money(cf(32))]]))+
panel('Working capital balances','Closing stocks for each selected month; balances are never summed.',trend('Working capital balances',[17,18,19,43].map(r=>trendSeries(finLabel('balance',r),month=>fv('balance',r,month)))))+
panel('Liquidity coverage',end+'. Ratios use closing balances; no annualization.',table(['Measure','Result','Calculation'],[['Current ratio',times(m.currentRatio),'Current assets / current liabilities'],['Current ratio excluding short-term investment',times(m.exInvestmentRatio),'(Current assets − short-term investment) / current liabilities'],['Cash coverage of current liabilities',times(m.cashRatio),'Cash / current liabilities'],['Cash + receivables coverage',times(m.receivableCoverage),'(Cash + trade receivables) / current liabilities'],['Operating cash / net sales',pct(percent(m.ocf,rv(31))),'Selected-period OCF / net sales after commission'],['Investment share of current assets',pct(percent(m.investment,m.assets)),'Short-term investment / current assets']]))+'</div>'+
panel('Working capital movement',`Opening: ${start}. Closing: ${end}. Changes in balances are not cash-flow adjustments; non-cash movements and classification changes may be included.`,table(['Balance','Opening','Closing','Change', '% of closing current assets'],[17,18,19,20,21,22,43,47].map(r=>[finLink('balance',r),money(priorBalance(r)),money(bs(r)),money(move(r)),[17,18,19,20,21].includes(r)?pct(percent(bs(r),m.assets)):'—']).concat([['Net working capital',money(sub(priorBalance(22),priorBalance(47))),money(m.nwc),money(sub(m.nwc,sub(priorBalance(22),priorBalance(47)))),'—']])))+
`<div class="grid">`+panel('Debt and funding exposure',end+' · '+unit()+'. Aggregated intercompany liabilities and short-term investments are excluded from net bank / lease debt.',table(['Funding balance','Amount'],[36,41,45,37,42].map(r=>[finLink('balance',r),money(bs(r))]).concat([['Total bank and lease debt',money(m.debt)],['Current bank and lease debt',money(m.currentDebt)],['Less: closing cash',money(m.cash)],['Net bank and lease debt',money(m.netDebt)],[finLink('balance',43,'Trade and other liabilities'),money(bs(43))]])))+
panel('Cash reconciliation',m.continuous?'Selected continuous period. Differences are retained exactly as supplied.':'Selected months are not continuous. Opening-to-closing roll-forward is left blank; classification and closing-balance checks remain available.',table(['Check','Amount'],[[finLink('cashflow',33,'Opening cash'),money(cf(33))],[finLink('cashflow',32,'Net cash movement'),money(cf(32))],[finLink('cashflow',34,'CFS closing cash'),money(cf(34))],['Opening + movement − CFS closing',money(m.cashRoll)],['Operating + investing + financing − net movement',money(sub(strictSum([cf(13),cf(20),cf(30)]),cf(32)))],['CFS closing − BS cash',money(sub(cf(34),m.cash))]]))+'</div>'+
panel('Cash & working-capital review','Calculated from supplied statements; review source reconciliation before acting.',signals.length?signals.join(''):empty())+
`<details class="panel"><summary>Detailed direct-method cash-flow statement</summary>${table(['Source line',unit()],[8,9,10,11,12,13,16,17,18,19,20,23,24,25,26,27,28,29,30,32,33,34].map(r=>[finLink('cashflow',r),money(cf(r))]))}</details><p class="source">Cash after capex is not distributable cash. Receivable aging, credit sales, supplier-only payables and repayment schedules are not supplied, so collection days, payment days and the cash-conversion cycle remain unavailable. No working-capital balance movement is presented as a confirmed cash release.</p>`;
};
